import {monitorLinkKey,saveMonitorLink,readMonitorLink} from './monitor-links.js?v=monitor-links-20261016';
import {defaultUsernameField,trackingField,surveyUsers,surveyIssues,newSurveyIssues,loadSurveyRows} from './survey-checks.js?v=monitor-links-20261016';
export function attachSurveyMonitor({state,$,makeTable}){
 let layers=[],account=null,timer=null,running=false,busy=false,previous=new Set(),generation=0;
 const message=(value,error=false)=>{$('monitor-status').textContent=value;$('monitor-status').classList.toggle('error',error);$('monitor-user-status').textContent=value;$('monitor-user-status').classList.toggle('error',error);};
 function stop(reason='Monitoring stopped.'){running=false;clearTimeout(timer);timer=null;message(reason);}
 function changed(){$('monitor-link-status').textContent='Selection changed. Save the monitoring link to keep these settings in this browser.';generation++;previous=new Set();stop('Settings changed. Run Check now or Start monitoring with your new selection.');$('monitor-summary').textContent='Previous results may be out of date. Run a new check.';}
 function auth(){if(!state.api||!state.user)throw Error('Sign in through Attribute Manager first.');if(Date.now()>=state.api.expires)throw Error('Session expired. Sign in again before monitoring.');return state.api;}
 async function action(task){if(busy||state.busy){message('Another operation is running. Try again when it finishes.',true);return;}busy=true;try{await task();}catch(error){stop(error.message);message(error.message,true);}finally{busy=false;}}
 const selectedLayers=()=>layers.filter(layer=>layer.check.checked);
 function selectedUsers(){return [...$('monitor-users').querySelectorAll('input:checked')].map(input=>input.value);}
 async function readLayer(layer,api,names){const missingIds=[];const rows=await loadSurveyRows(api,layer.url,layer.meta,names,(done,total)=>message('Reading '+layer.meta.name+': '+done+' readable / '+total+' listed records…'),id=>missingIds.push(id));return {rows,missingIds};}
 function assertCurrent(api,version){if(state.api!==api||generation!==version)throw Error('Session or monitor settings changed. Run a fresh check.');}
 async function loadLayers(){
  const api=auth();changed();const version=generation;const choices=[...$('layers').options].filter(option=>option.value);if(!choices.length)throw Error('Open a Feature Service in Attribute Manager first.');
  layers=[];account=api;$('monitor-layers').replaceChildren();$('monitor-users').replaceChildren();$('monitor-results').replaceChildren();$('monitor-coverage').replaceChildren();
  for(const option of choices){assertCurrent(api,version);const box=document.createElement('details'),title=document.createElement('summary');title.textContent=option.text;box.append(title);$('monitor-layers').append(box);
   try{const meta=await api.request(option.value);meta.objectIdField||=meta.fields?.find(field=>field.type==='esriFieldTypeOID')?.name;if(!meta.fields?.length||!meta.objectIdField)throw Error('No supported field schema / object ID.');
    const check=document.createElement('input');check.type='checkbox';check.setAttribute('aria-label','Monitor layer '+option.text);const label=document.createElement('label');label.className='null-toggle';label.append(check,document.createTextNode('Monitor every accessible record in this layer'));box.append(label);
    const source=document.createElement('select');source.setAttribute('aria-label',option.text+' username field');source.add(new Option('Choose the field containing surveyor usernames…',''));for(const field of meta.fields.filter(f=>f.type==='esriFieldTypeString'))source.add(new Option(field.name+' — '+(field.alias||field.name),field.name));const selectedSource=defaultUsernameField(meta,$('monitor-role').value);source.value=selectedSource;const sourceLabel=document.createElement('label');sourceLabel.textContent='Username values from this field (created_user in your example)';sourceLabel.append(source);box.append(sourceLabel);source.onchange=()=>{changed();$('monitor-users').replaceChildren();filterUsers();};
    const fields=[];for(const field of meta.fields){if(['esriFieldTypeOID','esriFieldTypeGlobalID','esriFieldTypeGeometry','esriFieldTypeBlob','esriFieldTypeRaster','esriFieldTypeXML'].includes(field.type)||Object.values(meta.editFieldsInfo||{}).includes(field.name))continue;const input=document.createElement('input');input.type='checkbox';input.value=field.name;input.setAttribute('aria-label',option.text+' required '+field.name);const row=document.createElement('label');row.className='null-toggle';row.append(input,document.createTextNode((field.alias||field.name)+' ['+field.name+']'));box.append(row);input.onchange=changed;fields.push(input);}
    check.onchange=()=>{changed();$('monitor-users').replaceChildren();};layers.push({url:option.value,meta,check,fields,source});const info=document.createElement('p');info.className='small';info.textContent='Creator: '+(meta.editFieldsInfo?.creatorField||'not exposed')+' · Last editor: '+(meta.editFieldsInfo?.editorField||'not exposed');box.append(info);
   }catch(error){const problem=document.createElement('p');problem.className='error';problem.textContent=error.message;box.append(problem);}
  }assertCurrent(api,version);message(layers.length+' accessible layer(s) loaded. Select every device and junction layer you need, then its required fields.');
 }
 $('monitor-load').onclick=()=>action(loadLayers);
 async function loadUsers(){
  const api=auth();if(api!==account||!layers.length)await loadLayers();let selected=selectedLayers();if(!selected.length){const current=layers.find(layer=>layer.url===$('layers').value);if(!current)throw Error('Choose a layer in Attribute Manager, or check a monitor layer above, then click Load username values again.');current.check.checked=true;current.check.closest('details').open=true;selected=[current];}const version=generation;const role=$('monitor-role').value,users=new Set(),coverage=[],activity=new Map(),oldUsers=new Set(selectedUsers());
  for(const layer of selected){try{trackingField(layer.meta,role,layer.source.value);const {rows,missingIds}=await readLayer(layer,api,[layer.source.value]);assertCurrent(api,version);surveyUsers(layer.meta,rows,role,layer.source.value).forEach(user=>users.add(user));for(const record of rows){const user=record.attributes[layer.source.value];if(typeof user!=='string'||!user.trim())continue;const info=activity.get(user)||{records:0,layers:new Set()};info.records++;info.layers.add(layer.meta.name);activity.set(user,info);}const untracked=rows.filter(row=>!row.attributes[trackingField(layer.meta,role,layer.source.value)]).length;coverage.push([layer.meta.name+' ['+layer.source.value+']',rows.length,untracked+' records without username. '+(missingIds.length?'PARTIAL: '+missingIds.length+' listed record(s) inaccessible or removed (examples: '+missingIds.slice(0,8).join(', ')+').':'No inaccessible IDs.')]);}catch(error){assertCurrent(api,version);coverage.push([layer.meta.name,'Not covered',error.message]);}}
  assertCurrent(api,version);$('monitor-users').replaceChildren();for(const user of [...users].sort()){const info=activity.get(user);addUser(user,info.records+' readable record(s) · '+[...info.layers].join(', '),oldUsers.has(user));}
  $('monitor-coverage').replaceChildren(makeTable(['Layer','Accessible records','Coverage notes'],coverage));$('monitor-user-coverage').replaceChildren(makeTable(['Layer / source field','Accessible records','Load result'],coverage));filterUsers();const failed=coverage.filter(row=>row[1]==='Not covered'||String(row[2]).includes('PARTIAL:')).length;message(users.size+' username value(s) loaded from readable records. '+(failed?failed+' layer(s) have incomplete coverage — see Load result below.':'Select the username checkboxes below.'),!!failed);
 }
 $('monitor-users-load').onclick=()=>action(loadUsers);
 function addUser(user,detail,checked=false){const input=document.createElement('input');input.type='checkbox';input.value=user;input.checked=checked;input.setAttribute('aria-label','Watch username '+user);input.onchange=changed;const label=document.createElement('label');label.className='null-toggle';label.dataset.username=user.toLowerCase();label.append(input,document.createTextNode(user+' — '+detail));$('monitor-users').append(label);}

 async function check(){
  const api=auth(),version=generation;if(api!==account)throw Error('Load monitor layers again for this sign-in.');const selected=selectedLayers(),users=selectedUsers(),role=$('monitor-role').value;if(!selected.length||!users.length)throw Error('Select layers and at least one username.');if(selected.some(layer=>!layer.fields.some(input=>input.checked)))throw Error('Choose required attributes for every selected layer. Your template is still pending.');
  const issues=[],coverage=[];let complete=true,recordCount=0;
  for(const layer of selected){try{trackingField(layer.meta,role,layer.source.value);const {rows,missingIds}=await readLayer(layer,api,[layer.source.value,...layer.fields.filter(input=>input.checked).map(input=>input.value),...(layer.meta.globalIdField?[layer.meta.globalIdField]:layer.meta.fields.filter(f=>f.type==='esriFieldTypeGlobalID').map(f=>f.name))]);assertCurrent(api,version);issues.push(...surveyIssues(layer.url,layer.meta,rows,role,users,layer.fields.filter(input=>input.checked).map(input=>input.value),layer.source.value));recordCount+=rows.length;const unknown=rows.filter(row=>!row.attributes[trackingField(layer.meta,role,layer.source.value)]).length;coverage.push([layer.meta.name,rows.length,(unknown?'Incomplete attribution: '+unknown+' record(s) without username. ':'')+(missingIds.length?'PARTIAL: '+missingIds.length+' inaccessible/removed record(s); examples: '+missingIds.slice(0,8).join(', '):'All listed rows read')]);if(unknown||missingIds.length)complete=false;}catch(error){assertCurrent(api,version);complete=false;coverage.push([layer.meta.name,'Not checked',error.message]);}}
  assertCurrent(api,version);const fresh=newSurveyIssues(issues,previous);if(complete)previous=new Set(issues.map(issue=>issue.key));else issues.forEach(issue=>previous.add(issue.key));
  $('monitor-results').replaceChildren(makeTable(['Layer','Tracking username','Global ID / Object ID','Required field','Missing value'],issues.slice(0,1000).map(issue=>[issue.layer,issue.user,issue.id,issue.field,issue.kind])));$('monitor-coverage').replaceChildren(makeTable(['Layer','Accessible records','Coverage notes'],coverage));
  const summary=issues.length+' missing required value(s); '+fresh.length+' new issue(s). '+recordCount+' accessible record(s) read across '+selected.length+' selected layer(s). '+(complete?'Scan complete for accessible records.':'Coverage incomplete — review problems below.')+(issues.length>1000?' Showing the first 1,000 issues.':'');$('monitor-summary').textContent=summary;message('Last check: '+new Date().toLocaleString('en-GB',{timeZone:'Africa/Kigali'})+' (Kigali)'+'. '+(running?'Monitoring continues while this app is open.':'Manual check finished.'));
  if(fresh.length&&typeof Notification!=='undefined'&&Notification.permission==='granted')new Notification('REG Survey Quality Monitor',{body:fresh.length+' new missing required attribute issue(s) for selected usernames. Open the app for details.'});
 }
 $('monitor-check').onclick=()=>action(check);
 async function tick(){if(!running)return;if(busy||state.busy){timer=setTimeout(tick,5000);return;}await action(check);if(running)timer=setTimeout(tick,Number($('monitor-interval').value));}
 $('monitor-start').onclick=()=>{if(busy||state.busy){message('Wait for the current operation to finish.',true);return;}clearTimeout(timer);running=true;tick();};
 $('monitor-stop').onclick=()=>stop();
 $('monitor-role').onchange=()=>{changed();for(const layer of layers)layer.source.value=defaultUsernameField(layer.meta,$('monitor-role').value);$('monitor-users').replaceChildren();filterUsers();};$('monitor-interval').onchange=changed;
 function filterUsers(){const term=$('monitor-user-search').value.trim().toLowerCase();let shown=0;for(const label of $('monitor-users').children){label.hidden=!label.dataset.username.includes(term);if(!label.hidden)shown++;}$('monitor-user-matches').textContent=shown+' / '+$('monitor-users').children.length+' usernames shown.'+(shown===0?' Clear the search or load username values from the correct field.':' Select the checkboxes below to monitor these users.');}
 $('monitor-user-search').oninput=filterUsers;
 function linkKey(){auth();return monitorLinkKey(state.api.portal,state.user.username);}
 $('monitor-link-form').onsubmit=e=>{e.preventDefault();action(async()=>{const chosen=selectedLayers(),users=selectedUsers();if(!chosen.length||!users.length)throw Error('Select layers and at least one username before saving a link.');const link={version:1,name:$('monitor-link-name').value.trim()||'My survey monitoring',role:$('monitor-role').value,interval:Number($('monitor-interval').value),users,layers:chosen.map(layer=>({url:layer.url,source:trackingField(layer.meta,$('monitor-role').value,layer.source.value),required:layer.fields.filter(input=>input.checked).map(input=>input.value)}))};saveMonitorLink(localStorage,linkKey(),link);$('monitor-link-status').textContent='Saved “'+link.name+'”: '+link.users.length+' username(s), '+link.layers.length+' layer(s). Stored only for this portal account in this browser. '+(link.layers.some(layer=>!layer.required.length)?'Required-field rules are still needed before monitoring.':'Use Start monitoring when ready.');message('Monitoring link saved. Saving does not start background checks.');});};
 $('monitor-link-restore').onclick=()=>action(async()=>{const link=readMonitorLink(localStorage,linkKey()),options=new Set([...$('layers').options].map(option=>option.value));if(link.layers.some(layer=>!options.has(layer.url)))throw Error('Open the saved Feature Service in Attribute Manager first. This link does not grant access to another service.');$('monitor-role').value=link.role;await loadLayers();for(const saved of link.layers){const layer=layers.find(item=>item.url===saved.url);if(!layer||!layer.meta.fields.some(field=>field.name===saved.source&&field.type==='esriFieldTypeString')||saved.required.some(name=>!layer.fields.some(input=>input.value===name)))throw Error('A saved layer or field is unavailable. Review the service schema and save an updated link.');layer.check.checked=true;layer.source.value=saved.source;layer.check.closest('details').open=true;layer.fields.forEach(input=>input.checked=saved.required.includes(input.value));}$('monitor-interval').value=String(link.interval);$('monitor-link-name').value=link.name;await loadUsers();const found=new Set([...$('monitor-users').querySelectorAll('input')].map(input=>input.value));for(const user of link.users)if(!found.has(user))addUser(user,'Saved selection — not found in this readable snapshot',true);for(const input of $('monitor-users').querySelectorAll('input'))input.checked=link.users.includes(input.value);filterUsers();$('monitor-link-status').textContent='Restored “'+link.name+'”. Review coverage and required fields, then Start monitoring. No checks were started automatically.';});
 $('monitor-notifications').onclick=async()=>{if(typeof Notification==='undefined'){message('Desktop notifications are unavailable in this browser. In-app alerts remain available.',true);return;}const permission=await Notification.requestPermission();message(permission==='granted'?'Desktop notifications enabled. Select usernames and start monitoring.':'Desktop notifications were not enabled. In-app alerts remain available.');};
 window.addEventListener('pagehide',()=>stop());
}
